if (numbers.length === 0) {
  throw new Error("Cannot compute the median of an empty list");
}
const sorted = [...numbers].sort((a, b) => a - b);
const middle = Math.floor(sorted.length / 2);
return sorted.length % 2 === 1
  ? sorted[middle]
  : (sorted[middle - 1] + sorted[middle]) / 2;

